(2, 'Which device is commonly used to store data permanently?', '["RAM","CPU","Hard Drive","Keyboard"]', 'Hard Drive'),
(2, 'What does CPU stand for?', '["Central Processing Unit","Computer Processing Utility","Central Program Unit","Computer Primary Unit"]', 'Central Processing Unit'),
(2, 'Which of these is NOT an output device?', '["Monitor","Printer","Speaker","Mouse"]', 'Mouse'),
